import unittest

def is_palindrome(s):
    if not isinstance(s, str):
        raise TypeError('expected a string')
    s = s.lower().replace(' ', '')
    return s == s[::-1]

class TestPalindrome(unittest.TestCase):
    def setUp(self):
        self.palindromes = ['racecar', 'madam', 'level', 'noon']
        self.non_palindromes = ['hello', 'world', 'python']

    def test_all_palindromes(self):
        for word in self.palindromes:
            self.assertTrue(is_palindrome(word), f'{word} should be a palindrome')

    def test_all_non_palindromes(self):
        for word in self.non_palindromes:
            self.assertFalse(is_palindrome(word), f'{word} should not be a palindrome')

unittest.main(argv=['x'], exit=False)

import unittest

def is_palindrome(s):
    if not isinstance(s, str):
        raise TypeError('expected a string')
    s = s.lower().replace(' ', '')
    return s == s[::-1]

class TestPalindrome(unittest.TestCase):
    def test_rejects_non_string(self):
        with self.assertRaises(TypeError):
            is_palindrome(12321)

    def test_rejects_none(self):
        with self.assertRaises(TypeError):
            is_palindrome(None)

    def test_still_works_for_strings(self):
        self.assertTrue(is_palindrome('level'))

unittest.main(argv=['x'], exit=False)

