import unittest

def parse_age(text):
    n = int(text)
    if n < 0:
        raise ValueError('negative')
    return n

class TestParseAge(unittest.TestCase):
    def test_negative_raises(self):
        with self.assertRaises(ValueError):
            parse_age('-1')

    def test_text_raises(self):
        with self.assertRaises(ValueError):
            parse_age('abc')

unittest.main(argv=['x'], exit=False)
